<?php
require_once __DIR__ . "/../config/conexionBDD.php"; require_once __DIR__ . "/../logica/sesion.php"; requerirLogin("login.php");
if($_SERVER['REQUEST_METHOD']==='POST') { if(!validarCSRF($_POST['csrf_token']??'')){http_response_code(400);exit('Token de seguridad inválido.');} $riesgo=trim($_POST['riesgo']??'');$cat=$_POST['categoria']??'operativo';$prob=$_POST['probabilidad']??'media';$impacto=$_POST['impacto']??'medio';$mit=trim($_POST['mitigacion']??'');$uid=(int)usuarioActual()['id']; if($riesgo!==''&&$mit!==''){ $st=$conexion->prepare('INSERT INTO matriz_riesgos(usuario_id,categoria,riesgo,probabilidad,impacto,mitigacion) VALUES(?,?,?,?,?,?)');$st->bind_param('isssss',$uid,$cat,$riesgo,$prob,$impacto,$mit);$st->execute();$st->close();header('Location: riesgos.php');exit();}}
if(esSupervisor()) $res=$conexion->query('SELECT r.*,u.nombre_completo FROM matriz_riesgos r JOIN usuario u ON u.id=r.usuario_id ORDER BY r.creado_en DESC'); else {$st=$conexion->prepare('SELECT r.*,u.nombre_completo FROM matriz_riesgos r JOIN usuario u ON u.id=r.usuario_id WHERE r.usuario_id=? ORDER BY r.creado_en DESC');$uid=(int)usuarioActual()['id'];$st->bind_param('i',$uid);$st->execute();$res=$st->get_result();}
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Control de riesgos</title><link rel="stylesheet" href="../css/estilos.css"></head><body><main class="contenedor"><p><a class="btn-secundario" href="../index.php">← Volver</a></p><h1>Control de riesgos</h1><p>Registre riesgos legales, laborales, operativos y de seguridad de la información, junto con acciones de mitigación.</p><form method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(tokenCSRF()) ?>"><div class="campo"><label>Riesgo *</label><input name="riesgo" maxlength="255" required></div><div class="campo"><label>Categoría</label><select name="categoria"><option value="legal">Legal</option><option value="datos_personales">Datos personales</option><option value="seguridad_informacion">Seguridad de información</option><option value="laboral">Laboral</option><option value="operativo">Operativo</option></select></div><div class="campo"><label>Probabilidad</label><select name="probabilidad"><option>baja</option><option selected>media</option><option>alta</option></select></div><div class="campo"><label>Impacto</label><select name="impacto"><option>bajo</option><option selected>medio</option><option>alto</option></select></div><div class="campo"><label>Mitigación *</label><textarea name="mitigacion" required></textarea></div><button>Registrar riesgo</button></form><h2>Riesgos registrados</h2><table class="tabla-listado"><tr><th>Riesgo</th><th>Categoría</th><th>Probabilidad</th><th>Impacto</th><th>Mitigación</th><th>Estado</th></tr><?php while($r=$res->fetch_assoc()){ ?><tr><td><?= htmlspecialchars($r['riesgo']) ?></td><td><?= htmlspecialchars($r['categoria']) ?></td><td><?= htmlspecialchars($r['probabilidad']) ?></td><td><?= htmlspecialchars($r['impacto']) ?></td><td><?= htmlspecialchars($r['mitigacion']) ?></td><td><?= htmlspecialchars($r['estado']) ?></td></tr><?php } ?></table></main></body></html>